from pathlib import Path

# Lectura tolerante: nunca crashea, marca bytes inválidos con U+FFFD
def leer_texto_tolerante(ruta) -> str:
    return Path(ruta).read_text(encoding='utf-8', errors='replace')

# Lectura estricta: falla rápido si el archivo no es UTF-8 válido
# (correcto cuando necesitas GARANTIZAR integridad, ej. datos financieros)
def leer_texto_estricto(ruta) -> str:
    with open(ruta, encoding='utf-8') as f:  # errors='strict' es el default
        return f.read()

# Detección de encoding cuando el origen es desconocido (archivos legacy)
def leer_autodetectar(ruta) -> str:
    raw = Path(ruta).read_bytes()
    # BOM de UTF-8: empieza con b'\xef\xbb\xbf'
    if raw.startswith(b'\xef\xbb\xbf'):
        return raw.decode('utf-8-sig')
    try:
        return raw.decode('utf-8')
    except UnicodeDecodeError:
        return raw.decode('latin-1')  # latin-1 NUNCA falla: mapea los 256 bytes

# Opciones de errors (memoriza las 3 primeras):
# 'strict'  → UnicodeDecodeError (default)
# 'replace' → sustituye byte inválido por U+FFFD (el rombo )
# 'ignore'  → descarta bytes inválidos en silencio (peligroso: pierde datos)
# 'backslashreplace' → muestra \xff (útil para debug)

