import json
from datetime import datetime
from pathlib import Path

# Estrategia profesional: ISO 8601 al guardar, datetime real al cargar

def _serializar(obj):
    """default hook: convierte tipos no serializables a string."""
    if isinstance(obj, datetime):
        return obj.isoformat()          # '2026-09-29T10:30:00' — estándar y ordenable
    raise TypeError(f'Tipo no serializable: {type(obj).__name__}')

def _deserializar(dct):
    """object_hook: reconstruye datetimes desde ISO."""
    if 'creada' in dct:
        try:
            dct['creada'] = datetime.fromisoformat(dct['creada'])
        except (ValueError, TypeError):
            pass
    return dct

def guardar_notas(ruta, notas):
    # Escritura atómica (ver M1.3-007): nunca dejes un JSON a medio escribir
    tmp = Path(ruta).with_suffix('.tmp')
    tmp.write_text(
        json.dumps(notas, ensure_ascii=False, indent=2, default=_serializar),
        encoding='utf-8'
    )
    tmp.replace(ruta)

def leer_notas(ruta):
    path = Path(ruta)
    if not path.exists():
        return []
    try:
        return json.loads(path.read_text(encoding='utf-8'), object_hook=_deserializar)
    except json.JSONDecodeError:
        # Nunca crashees por un archivo corrupto: recupera y avisa
        path.replace(path.with_suffix('.corrupto'))
        return []

# Mapa de pérdidas del round-trip que debes memorizar:
# datetime        → TypeError (sin default)      → reconstruir con object_hook
# set             → TypeError (siempre)          → list() manual + documentar
# tuple           → list (silencioso)            → marcador {'__tuple__': [...]}
# claves int      → string (silencioso)          → convertir al cargar
# float grandes   → posible pérdida de precisión → str o Decimal
# None/True/False → null/true/false (correcto)

