from collections import Counter

# Generator: el patrón base de streaming
def lineas_de_error(ruta):
    with open(ruta, encoding='utf-8') as f:
        for linea in f:
            if 'ERROR' in linea:
                yield linea

# Pipelines encadenados: cada etapa es perezosa, nada se materializa
def sin_timestamp(lineas):
    for l in lineas:
        yield l.split(' ', 2)[-1].strip()

pipeline = sin_timestamp(lineas_de_error('app.log'))
primeros_5 = list(islice(pipeline, 5))   # lee SOLO lo necesario del archivo

# Contar sin acumular: O(1) memoria aunque haya 1M de errores
def contar_errores(ruta):
    total = 0
    with open(ruta, encoding='utf-8') as f:
        for linea in f:
            if 'ERROR' in linea:
                total += 1
    return total

# Estadísticas por streaming con Counter
def top_mensajes_error(ruta, n=10):
    c = Counter()
    with open(ruta, encoding='utf-8') as f:
        for linea in f:
            if 'ERROR' in linea:
                c[linea.split(' ', 2)[-1].strip()] += 1
    return c.most_common(n)

