import json
import os
import tempfile
from datetime import datetime
from pathlib import Path

class NoteStore:
    """Persistencia de notas con las 4 cláusulas + API de dominio completa."""

    def __init__(self, ruta):
        self.ruta = Path(ruta)
        self.notas = self._cargar()

    # ---- Cláusula 1: lectura tolerante ----
    def _cargar(self):
        try:
            datos = json.loads(self.ruta.read_text(encoding='utf-8'))
            return datos if isinstance(datos, list) else []
        except FileNotFoundError:
            return []
        except json.JSONDecodeError:
            # Respaldar el corrupto: los datos del usuario se investigan, no se borran
            backup = self.ruta.with_suffix('.corrupto')
            try:
                self.ruta.replace(backup)
            except OSError:
                pass
            return []

    # ---- Cláusulas 2+3+4: escritura atómica, ISO, UTF-8 ----
    def _guardar(self):
        self.ruta.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=self.ruta.parent, suffix='.tmp')
        try:
            with os.fdopen(fd, 'w', encoding='utf-8') as f:
                json.dump(self.notas, f, ensure_ascii=False, indent=2, default=str)
            os.replace(tmp, self.ruta)
        except BaseException:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise

    # ---- API de dominio ----
    def agregar(self, texto: str) -> dict:
        nota = {'texto': texto, 'creada': datetime.now().isoformat()}
        self.notas.append(nota)
        self._guardar()
        return nota

    def eliminar(self, indice: int) -> None:
        del self.notas[indice]   # IndexError si fuera de rango: correcto, no silenciar
        self._guardar()

    def buscar(self, termino: str):
        t = termino.lower()
        return (n for n in self.notas if t in n['texto'].lower())  # generator: M1.3-006

    def exportar_txt(self, ruta):
        with open(ruta, 'w', encoding='utf-8') as f:
            for n in self.notas:
                f.write(f"[{n['creada']}] {n['texto']}\n")

